package de.monoschwarz.raster;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.media.session.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import android.text.*;
import java.text.SimpleDateFormat;
import java.util.*;

/** Mono Schwarz: portrait-first launcher with three independent experiences. */
public class MainActivity extends Activity {
    private final String[] MODES={"LISTEN","TYPE","PLAY"};
    private String mode="TYPE", theme="Dark", layer="ABC", query="";
    private boolean shift=false, haptics=true, sounds=false;
    private int fg,bg,panel,key,edge,muted;
    private LinearLayout root,display,controls;
    private TextView clock;
    private android.content.SharedPreferences prefs;
    private final ArrayList<ResolveInfo> installed=new ArrayList<>();
    private MediaSessionManager sessions;
    private MediaController active;
    private final Handler handler=new Handler(android.os.Looper.getMainLooper());
    private final Runnable ticker=new Runnable(){public void run(){if(clock!=null)clock.setText(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()));handler.postDelayed(this,30000);}};

    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("mono",MODE_PRIVATE);mode=prefs.getString("mode","TYPE");theme=prefs.getString("theme","Dark");haptics=prefs.getBoolean("haptics",true);sounds=prefs.getBoolean("sounds",false);sessions=(MediaSessionManager)getSystemService(MEDIA_SESSION_SERVICE);loadApps();render();handler.post(ticker);}
    @Override protected void onResume(){super.onResume();loadApps();if(root!=null)render();}
    @Override protected void onDestroy(){handler.removeCallbacks(ticker);super.onDestroy();}
    @Override public void onBackPressed(){if(!mode.equals("TYPE")){setMode("TYPE");return;}super.onBackPressed();}
    private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),edge);return d;}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    private LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(fg);t.setTextSize(size);t.setGravity(Gravity.CENTER);if(bold)t.setTypeface(null,1);return t;}
    private LinearLayout.LayoutParams w(int width,int height,float weight){return new LinearLayout.LayoutParams(width<0?width:dp(width),height<0?height:dp(height),weight);}
    private void palette(){boolean light=theme.equals("Light");boolean minimal=theme.equals("Minimalist");bg=light?0xfff1f1ed:minimal?0xfffafafa:0xff101113;panel=light?0xffffffff:minimal?0xffffffff:0xff222428;key=light?0xffe0e0dc:minimal?0xfff3f3f3:0xff34383e;fg=light||minimal?0xff1b1b1b:0xfff5f5f4;muted=light||minimal?0xff707070:0xffa5a8aa;edge=light||minimal?0xffd6d6d6:0xff4b4e53;getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(light||minimal?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);}
    private void render(){palette();root=vertical();root.setBackgroundColor(bg);root.setFitsSystemWindows(true);display=vertical();display.setPadding(dp(14),dp(10),dp(14),dp(10));display.setBackground(shape(panel,18));LinearLayout.LayoutParams a=w(-1,0,618);a.setMargins(dp(5),dp(4),dp(5),dp(3));root.addView(display,a);controls=vertical();controls.setPadding(dp(6),dp(4),dp(6),dp(4));LinearLayout.LayoutParams c=w(-1,0,382);c.setMargins(dp(4),0,dp(4),dp(4));root.addView(controls,c);setContentView(root);header();if(mode.equals("TYPE"))typeDisplay();else if(mode.equals("LISTEN"))listenDisplay();else playDisplay();modeSwitch();if(mode.equals("TYPE"))typeControls();else if(mode.equals("LISTEN"))listenControls();else playControls();utilityRow();}
    private void header(){LinearLayout h=horizontal();TextView brand=text("MONO SCHWARZ",12,true);brand.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);h.addView(brand,w(0,30,1));TextView menu=text("⚙",23,false);h.addView(menu,w(38,30,0));menu.setOnClickListener(v->settings());display.addView(h);clock=text("",44,false);display.addView(clock,w(-1,0,1));clock.setText(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()));TextView date=text(new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),13,false);date.setTextColor(muted);display.addView(date,w(-1,24,0));}
    private void typeDisplay(){TextView title=text("TYPE  /  QWERTZ",11,true);title.setTextColor(muted);display.addView(title,w(-1,24,0));TextView input=text(query.isEmpty()?"Search installed apps":query,16,false);input.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);input.setPadding(dp(12),0,dp(12),0);input.setBackground(shape(key,10));display.addView(input,w(-1,44,0));input.setOnClickListener(v->showDrawer());LinearLayout shortcuts=horizontal();display.addView(shortcuts,w(-1,0,2));int max=theme.equals("Minimalist")?4:5;int shown=0;for(ResolveInfo ri:installed){if(shown++>=max)break;String name=ri.loadLabel(getPackageManager()).toString();TextView tile=text(name.length()>11?name.substring(0,10)+"…":name,11,true);tile.setBackground(shape(key,10));LinearLayout.LayoutParams p=w(0,65,1);p.setMargins(dp(2),0,dp(2),0);shortcuts.addView(tile,p);tile.setOnClickListener(v->launch(ri));}Button drawer=button("ALL APPS  ·  "+installed.size());display.addView(drawer,w(-1,40,0));drawer.setOnClickListener(v->showDrawer());}
    private void listenDisplay(){TextView title=text("LISTEN  /  MEDIA",12,true);title.setTextColor(muted);display.addView(title,w(-1,32,0));TextView song=text("No active media session",19,true);display.addView(song,w(-1,0,1));TextView detail=text("Enable notification access to control compatible players",12,false);detail.setTextColor(muted);display.addView(detail,w(-1,0,1));MediaController m=media();if(m!=null){android.media.MediaMetadata md=m.getMetadata();if(md!=null){String name=md.getString(android.media.MediaMetadata.METADATA_KEY_TITLE);String artist=md.getString(android.media.MediaMetadata.METADATA_KEY_ARTIST);song.setText(name==null?m.getPackageName():name);detail.setText(artist==null?m.getPackageName():artist);}}Button access=button("MEDIA ACCESS / REFRESH");display.addView(access,w(-1,42,0));access.setOnClickListener(v->{if(!mediaAccess())startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS));else render();});}
    private void playDisplay(){TextView title=text("PLAY  /  GAME HUB",12,true);title.setTextColor(muted);display.addView(title,w(-1,34,0));ArrayList<ResolveInfo> games=games();TextView info=text(games.isEmpty()?"No recognised installed games":"INSTALLED GAMES  ·  "+games.size(),16,true);display.addView(info,w(-1,0,1));ScrollView scroll=new ScrollView(this);LinearLayout list=vertical();scroll.addView(list);display.addView(scroll,w(-1,0,3));for(ResolveInfo ri:games){Button b=button(ri.loadLabel(getPackageManager()).toString());list.addView(b,w(-1,43,0));b.setOnClickListener(v->launch(ri));}TextView note=text("Controller works with supported games; it cannot inject input into arbitrary apps.",11,false);note.setTextColor(muted);display.addView(note,w(-1,46,0));}
    private void modeSwitch(){LinearLayout bar=horizontal();controls.addView(bar,w(-1,39,0));for(String m:MODES){Button b=button(m.equals(mode)?"● "+m:m);LinearLayout.LayoutParams p=w(0,-1,1);p.setMargins(dp(2),0,dp(2),0);bar.addView(b,p);b.setOnClickListener(v->setMode(m));}}
    private void setMode(String m){mode=m;prefs.edit().putString("mode",m).apply();render();}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(fg);b.setTextSize(s.length()>12?10:13);b.setAllCaps(false);b.setPadding(dp(2),0,dp(2),0);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setBackground(shape(key,8));return b;}
    private void row(String... keys){LinearLayout r=horizontal();controls.addView(r,w(-1,0,1));for(String k:keys){Button b=button(k);LinearLayout.LayoutParams p=w(0,-1,k.equals("SPACE")?3:1);p.setMargins(dp(2),dp(2),dp(2),dp(2));r.addView(b,p);b.setOnClickListener(v->{feedback(v);typeKey(k);});}}
    private void typeControls(){if(layer.equals("NUM")){row("1","2","3","4","5","6","7","8","9","0");row("@","#","€","%","&","-","+","(",")");}else if(layer.equals("SYM")){row("!","?","/","\\","=","*","_",":",";");row("[","]","{","}","<",">","~","^");}else{row("Q","W","E","R","T","Z","U","I","O","P");row("A","S","D","F","G","H","J","K","L","Ä");row("⇧","Y","X","C","V","B","N","M","Ö","Ü");}row("ALT","ß",",","SPACE",".","⌫","↵");}
    private void typeKey(String k){switch(k){case "ALT":layer=layer.equals("ABC")?"NUM":layer.equals("NUM")?"SYM":"ABC";render();return;case "⇧":shift=!shift;return;case "⌫":if(!query.isEmpty())query=query.substring(0,query.length()-1);break;case "↵":searchAndLaunch();return;case "SPACE":query+=" ";break;default:query+=shift?k:k.toLowerCase(Locale.GERMAN);shift=false;}render();}
    private void listenControls(){LinearLayout row=horizontal();controls.addView(row,w(-1,0,1));String[] keys={"MENU","◀◀","●","▶▶","▶ / ❚❚"};for(String k:keys){Button b=button(k);LinearLayout.LayoutParams p=w(0,-1,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(b,p);b.setOnClickListener(v->{feedback(v);if(k.equals("MENU")){setMode("TYPE");return;}MediaController m=media();if(m==null){Toast.makeText(this,"No accessible active media session",Toast.LENGTH_SHORT).show();return;}MediaController.TransportControls tc=m.getTransportControls();if(k.equals("◀◀"))tc.skipToPrevious();else if(k.equals("▶▶"))tc.skipToNext();else if(k.equals("▶ / ❚❚")){android.media.session.PlaybackState s=m.getPlaybackState();if(s!=null&&s.getState()==android.media.session.PlaybackState.STATE_PLAYING)tc.pause();else tc.play();}else render();});}}
    private void playControls(){LinearLayout r=horizontal();controls.addView(r,w(-1,0,1));String[] k={"↑","←","↓","→","A","B","X","Y"};for(String s:k){Button b=button(s);LinearLayout.LayoutParams p=w(0,-1,1);p.setMargins(dp(2),dp(3),dp(2),dp(3));r.addView(b,p);b.setOnClickListener(v->{feedback(v);Toast.makeText(this,"Controller requires a compatible game integration",Toast.LENGTH_SHORT).show();});}LinearLayout lower=horizontal();controls.addView(lower,w(-1,39,0));for(String s:new String[]{"SELECT","START","GAME HUB"}){Button b=button(s);lower.addView(b,w(0,-1,1));b.setOnClickListener(v->{feedback(v);if(s.equals("GAME HUB"))render();else Toast.makeText(this,"Available in compatible games",Toast.LENGTH_SHORT).show();});}}
    private void utilityRow(){LinearLayout r=horizontal();controls.addView(r,w(-1,37,0));for(String s:new String[]{"☎","⌂","↶","⏻"}){Button b=button(s);LinearLayout.LayoutParams p=w(0,-1,1);p.setMargins(dp(2),dp(2),dp(2),dp(2));r.addView(b,p);b.setOnClickListener(v->{feedback(v);try{if(s.equals("☎"))startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:")));else if(s.equals("⌂"))setMode("TYPE");else if(s.equals("↶"))onBackPressed();else new AlertDialog.Builder(this).setTitle("Power / display").setMessage("Android restricts third-party launchers from opening the system power menu or locking the screen without additional privileges. Use the device power button.").setPositiveButton("OK",null).show();}catch(Exception e){Toast.makeText(this,"Action unavailable on this device",Toast.LENGTH_SHORT).show();}});}}
    private void feedback(View v){if(haptics)v.performHapticFeedback(android.view.HapticFeedbackConstants.KEYBOARD_TAP);if(sounds)v.playSoundEffect(android.view.SoundEffectConstants.CLICK);}
    private void loadApps(){installed.clear();Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);installed.addAll(getPackageManager().queryIntentActivities(intent,0));Collections.sort(installed,(a,b)->a.loadLabel(getPackageManager()).toString().compareToIgnoreCase(b.loadLabel(getPackageManager()).toString()));}
    private ArrayList<ResolveInfo> games(){ArrayList<ResolveInfo> out=new ArrayList<>();for(ResolveInfo ri:installed){try{ApplicationInfo ai=getPackageManager().getApplicationInfo(ri.activityInfo.packageName,0);if(android.os.Build.VERSION.SDK_INT>=26&&ai.category==ApplicationInfo.CATEGORY_GAME)out.add(ri);}catch(Exception ignored){}}return out;}
    private void launch(ResolveInfo ri){try{Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LAUNCHER);i.setClassName(ri.activityInfo.packageName,ri.activityInfo.name);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}catch(Exception e){Toast.makeText(this,"Unable to open app",Toast.LENGTH_SHORT).show();}}
    private void searchAndLaunch(){String q=query.trim().toLowerCase(Locale.ROOT);if(q.isEmpty()){showDrawer();return;}for(ResolveInfo ri:installed){if(ri.loadLabel(getPackageManager()).toString().toLowerCase(Locale.ROOT).contains(q)){launch(ri);return;}}Toast.makeText(this,"No matching app",Toast.LENGTH_SHORT).show();}
    private void showDrawer(){String[] names=new String[installed.size()];for(int i=0;i<names.length;i++)names[i]=installed.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Installed apps").setItems(names,(d,i)->launch(installed.get(i))).setNegativeButton("Close",null).show();}
    private void settings(){String[] items={"Theme: "+theme,"Haptics: "+(haptics?"On":"Off"),"Key sounds: "+(sounds?"On":"Off"),"Enable system QWERTZ keyboard","Choose default launcher","Media notification access"};new AlertDialog.Builder(this).setTitle("Mono Schwarz settings").setItems(items,(d,i)->{switch(i){case 0:new AlertDialog.Builder(this).setTitle("Theme").setItems(new String[]{"Dark","Light","Minimalist"},(x,n)->{theme=new String[]{"Dark","Light","Minimalist"}[n];prefs.edit().putString("theme",theme).apply();render();}).show();break;case 1:haptics=!haptics;prefs.edit().putBoolean("haptics",haptics).apply();break;case 2:sounds=!sounds;prefs.edit().putBoolean("sounds",sounds).apply();break;case 3:startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS));break;case 4:startActivity(new Intent(Settings.ACTION_HOME_SETTINGS));break;case 5:startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS));break;}}).show();}
    private boolean mediaAccess(){return android.provider.Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners")!=null&&android.provider.Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners").contains(getPackageName());}
    private MediaController media(){if(!mediaAccess())return null;try{android.content.ComponentName component=new android.content.ComponentName(this,MediaAccessService.class);List<MediaController> list=sessions.getActiveSessions(component);if(list.isEmpty())return null;for(MediaController c:list){android.media.session.PlaybackState s=c.getPlaybackState();if(s!=null&&s.getState()==android.media.session.PlaybackState.STATE_PLAYING)return c;}return list.get(0);}catch(Exception e){return null;}}
}
